TPL.push({id:'bankconf',cat:'conf',ar:'طلب مصادقة بنكية',en:'Bank Confirmation Request',isa:'505',wp:'E-05 E-06',desc:'مصادقة إيجابية من البنك على الأرصدة والتسهيلات والضمانات والقيود؛ تُرسل وتُستلم تحت رقابة المراجع.',
vars:[['bank','اسم البنك',''],['confdate','تاريخ المصادقة','']],
secs:[['head','',['السادة/ {{bank}}','الموضوع: طلب مصادقة على الأرصدة والمعاملات كما في {{period}}']],
['body','',['نرجو تزويد مراجعي حساباتنا {{firm}} مباشرة بالمعلومات التالية عن جميع حساباتنا ومعاملاتنا لديكم كما في نهاية يوم العمل {{period}}، وذلك لأغراض المراجعة:','- أرصدة جميع الحسابات (جارية، ودائع، قروض، حسابات بعملات أجنبية) مع أرقامها وعملاتها وأسعار الفائدة وتواريخ الاستحقاق.','- التسهيلات الائتمانية الممنوحة والمستخدم منها والضمانات المقدمة منا أو لصالحنا.','- خطابات الضمان والاعتمادات المستندية القائمة والالتزامات العرضية.','- المشتقات والعقود الآجلة للعملات وأي أدوات مالية أخرى.','- أي رهون أو قيود على الأرصدة أو الأصول.','- المفوضون بالتوقيع على الحسابات.','يرجى إرسال الرد مباشرة إلى عنوان المراجع أدناه، علمًا بأن هذا الطلب لا يُعفي من الإفادة بأي معلومات أخرى لديكم ذات صلة.']],
['sign','',['عن شركة {{company}}: .................. (توقيع مفوض)','عنوان الرد: {{firm}} — {{city}} — عناية الشريك {{partner}}']]]});

